from pysat.formula import CNF
from pysat.solvers import Glucose4

n = 31
N = 2*n
# variables: x[v][i] = value v placed at position i (i from 0 to N-1), with second copy at i+v+1
# v from 1..n, i from 0..N-2-v
var = {}
c = 1
for v in range(1, n+1):
    for i in range(N-1-v):
        var[(v,i)] = c
        c += 1

clauses = []
# each value has exactly one placement
for v in range(1, n+1):
    lits = [var[(v,i)] for i in range(N-1-v)]
    clauses.append(lits)
    for a in range(len(lits)):
        for b in range(a+1, len(lits)):
            clauses.append([-lits[a], -lits[b]])

# each position has exactly one value
# build which (v,i) placements occupy position p
occ = {p: [] for p in range(N)}
for v in range(1, n+1):
    for i in range(N-1-v):
        occ[i].append(var[(v,i)])
        occ[i+v+1].append(var[(v,i)])

for p in range(N):
    lits = occ[p]
    clauses.append(lits)
    for a in range(len(lits)):
        for b in range(a+1, len(lits)):
            clauses.append([-lits[a], -lits[b]])

solver = Glucose4()
for cl in clauses:
    solver.add_clause(cl)
print(solver.solve())
model = solver.get_model()
seq = [0]*N
for v in range(1, n+1):
    for i in range(N-1-v):
        if model[var[(v,i)]-1] > 0:
            seq[i] = v
            seq[i+v+1] = v
print(seq)
